{"filePath":"c:\Users\drvoj\Documents\GitHub\aspnet-tvz\src\Playlist\Playlist\Controllers\AccountController.cs","oldString":"using Microsoft.AspNetCore.Mvc;
using Playlist.Repositories;

namespace Playlist.Controllers
{
    public class AccountController : Controller
    {
        private readonly UserRepository _userRepository;

        public AccountController(UserRepository userRepository)
        {
            _userRepository = userRepository;
        }

        public IActionResult SignIn()
        {
            return View(_userRepository.GetAll());
        }

        [HttpPost]
        public IActionResult SignIn(int userId)
        {
            var user = _userRepository.GetById(userId);

            if (user == null)
            {
                return NotFound();
            }

            HttpContext.Session.SetInt32("UserId", user.UserId);
            HttpContext.Session.SetString("Username", user.Username);

            return RedirectToAction(nameof(Profile), new { id = user.UserId });
        }

        public IActionResult Profile(int? id)
        {
            if (id == null)
