### **DTO za frontend** (`ApiDtos.cs`):
```csharp
public class PlaylistDto
{
    public int PlaylistId { get; set; }
    public string Name { get; set; }
    public string Description { get; set; }
    public DateTime CreatedAt { get; set; }
    public bool IsPublic { get; set; }
    public int Likes { get; set; }
    public UserSummaryDto? Owner { get; set; }  // ← Samo id + username!
    public List<SongSummaryDto> Songs { get; set; }  // ← Samo id + title + artist!
    public List<PlaylistAttachmentDto> Attachments { get; set; }
}

public class UserSummaryDto
{
    public int UserId { get; set; }
    public string Username { get; set; }
}

public class SongSummaryDto
{
    public int SongId { get; set; }
    public string Title { get; set; }
    public string Artist { get; set; }
    public string Genre { get; set; }
}
```

### **Extension metoda za mapiranje**:
```csharp
public static PlaylistDto ToDto(this Playlist playlist)
    => new()
    {
        PlaylistId = playlist.PlaylistId,
        Name = playlist.Name,
        Description = playlist.Description,
        CreatedAt = playlist.CreatedAt,
        IsPublic = playlist.IsPublic,
        Likes = playlist.Likes,
        Owner = playlist.Owner == null ? null : new UserSummaryDto
        {
            UserId = playlist.Owner.UserId,
            Username = playlist.Owner.Username
        },
        Songs = playlist.Songs?.Select(s => new SongSummaryDto
        {
            SongId = s.SongId,
            Title = s.Title,
            Artist = s.Artist?.StageName ?? string.Empty,
            Genre = s.Genre?.Name ?? string.Empty
        }).ToList() ?? new List<SongSummaryDto>(),
        Attachments = playlist.Attachments?.Select(a => a.ToDto()).ToList() 
            ?? new List<PlaylistAttachmentDto>()
    };
```

